typedef unsigned int size_t;

#define NULL 0
#define NEW new(0, __FILE__, __LINE__)
#define CHEAT_LAST 22
#define GT_CHEAT_RAINBOW_SHORT 0
#define MAX_CHEATS_PER_SCREEN 2
#define PHONE_SCREEN_LEFT 377
#define PHONE_SCREEN_TOP 73
#define PHONE_LIST_VERT_SPACING 32
#define PHONE_TOGLE_TOP_OFFSET 18

void *operator new(size_t, unsigned int, const char *, int);

class stringx
{
public:
    stringx();
    stringx(const char *, int = -1);
    stringx(const stringx &);
    ~stringx();
};

class glyph_info
{
    char padding[16];

public:
    int cell_height;
};

class Font
{
public:
    enum HORIZJUST
    {
        HORIZJUST_LEFT,
        HORIZJUST_CENTER,
        HORIZJUST_RIGHT
    };
    enum VERTJUST
    {
        VERTJUST_TOP,
        VERTJUST_CENTER,
        VERTJUST_BOTTOM
    };

    glyph_info *getGlyph(char c);
};

class FEMenu;

class FEMenuEntry
{
public:
    int entry_num;
    FEMenuEntry *next;
    FEMenuEntry *previous;
    FEMenu *menu;
    bool highlight;
    bool disabled;
    char layout[62];
    FEMenuEntry *up;
    FEMenuEntry *down;
    FEMenuEntry *left;
    FEMenuEntry *right;

    FEMenuEntry(stringx text, FEMenu *menu, bool disabled, Font *font);
    virtual ~FEMenuEntry();
    virtual void Load();
    virtual void OnSelect();
    virtual void Highlight(bool highlighted = true, bool animate = true);
    virtual void Disable(bool disabled = true);
    virtual bool GetDisable();
    virtual void Draw();
    virtual void Update(float time_inc);
    virtual void TurnOn(bool enabled);
    virtual void SetSpecialColor(unsigned int normal, unsigned int highlighted);
    virtual void SetSpecialScale(float normal, float highlighted);
    virtual bool GetSpecialScale(float &normal, float &highlighted);
    virtual void SetNoFlash(bool disabled);
    virtual float GetHighlightIntensity();
    virtual void SetPos(float x, float y);
    virtual void SetLocation3D(char location[16]);
    virtual void SetText(stringx text);
    virtual void SetHJustify(Font::HORIZJUST justify);
    virtual void SetVJustify(Font::VERTJUST justify);
    virtual void SetLineSpacing(int spacing);
};

class FEMenu
{
    char layout[0x70];

public:
    virtual ~FEMenu();
    virtual void setBack(FEMenu *, int = 1);
    virtual void setHigh(FEMenuEntry *, bool = true);
    virtual void setVis(FEMenuEntry *);
    virtual void Add(FEMenuEntry *);
};

class FEMultiMenu : public FEMenu
{
    char layout[0xec];
};

class TextString;
class PanelQuad;
class GraphicalMenuSystem;

struct FrontEndManager
{
    Font font_body;
};

class GlobalDataClass
{
public:
    bool isCheatUnlocked(int cheat) const;
};

extern GlobalDataClass globalCareerData;
extern stringx ksGlobalTextArray[];
extern FrontEndManager frontendmanager;

class CheatCodeMenu : public FEMultiMenu
{
private:
    FEMenuEntry *cheats[MAX_CHEATS_PER_SCREEN];
    int menu_entry_cheat_index[MAX_CHEATS_PER_SCREEN];
    GraphicalMenuSystem *sys;
    int next_down, next_up;
    TextString *toggle_state[MAX_CHEATS_PER_SCREEN];
    PanelQuad *arrow_up;
    PanelQuad *arrow_down;

public:
    void ReOrderEntries(const int start);
    void ResetToggles();
    void ResetUpDownArrows();
};

void CheatCodeMenu::ReOrderEntries(const int start)
{
	int i = start, entry_index = 0;

	while(i < CHEAT_LAST && entry_index < MAX_CHEATS_PER_SCREEN)
	{
		if(globalCareerData.isCheatUnlocked(i))
		{
			if(cheats[entry_index] == NULL) // this entry hasn't been created yet
			{
				cheats[entry_index] = NEW FEMenuEntry(ksGlobalTextArray[GT_CHEAT_RAINBOW_SHORT + i], this, false, &frontendmanager.font_body);
				if(entry_index != 0)
				{
					cheats[entry_index]->up = cheats[entry_index - 1];
					cheats[entry_index - 1]->down = cheats[entry_index];
				}
				Add(cheats[entry_index]);
			}
			else // an entry already exists here
			{
				// change its text
				cheats[entry_index]->SetText(ksGlobalTextArray[GT_CHEAT_RAINBOW_SHORT + i]);
			}
			cheats[entry_index]->SetPos(PHONE_SCREEN_LEFT, PHONE_SCREEN_TOP + PHONE_TOGLE_TOP_OFFSET + PHONE_LIST_VERT_SPACING * entry_index);
			cheats[entry_index]->SetVJustify(Font::VERTJUST_TOP);
			cheats[entry_index]->SetHJustify(Font::HORIZJUST_LEFT);
			cheats[entry_index]->SetLineSpacing(frontendmanager.font_body.getGlyph('A')->cell_height*0.6f);
			menu_entry_cheat_index[entry_index] = i;
			entry_index++;
		}
		i++;
	}

	// Now set all the on/off toggles at the right of the screen
	ResetToggles();
	// And make the arrows show or not show as appropriate
	ResetUpDownArrows();
}
